import { ConflictError, normalizeToBaseError, NotFoundError } from "@zudojs/errors";

const tasks = new Map([[1, { id: 1, title: "Buy milk", done: false }]]);

function complete(id) {
  const task = tasks.get(id);
  if (!task) throw new NotFoundError(`Task ${id} not found`);
  if (task.done) throw new ConflictError(`Task ${id} is already done`);
  const updated = { ...task, done: true };
  tasks.set(id, updated);
  return updated;
}

for (const id of [1, 1, 5]) {
  try {
    complete(id);
    console.log(200);
  } catch (thrown) {
    const error = normalizeToBaseError(thrown);
    console.log(error.statusCode, error.code);
  }
}

