import { invalidFieldIssue, requiredFieldIssue, ValidationError } from "@zudojs/errors";

function checkRow(row) {
  const issues = [];
  if (row.title === undefined) issues.push(requiredFieldIssue("title"));
  if (!["low", "normal", "high"].includes(row.priority)) {
    issues.push(invalidFieldIssue("priority", "Priority must be low, normal or high"));
  }
  if (issues.length > 0) {
    throw new ValidationError("The import file has problems", { issues });
  }
  return "ok";
}

console.log(checkRow({ title: "Buy milk", priority: "low" }));
try {
  checkRow({ priority: "urgent" });
} catch (error) {
  console.log(error.statusCode, error.issueCount, error.issues?.map((i) => i.field).join(","));
}

